      .button-danger:hover {
        background: linear-gradient(135deg, var(--danger-strong), #e11d48);
      }

      .confirm-dialog {
        width: min(calc(100vw - 2rem), 31rem);
        max-height: calc(100vh - 2rem);
        overflow: auto;
        border: 1px solid rgb(255 255 255 / 0.14);
        border-radius: 1.5rem;
        background: linear-gradient(145deg, var(--panel-strong), var(--panel));
        color: var(--text);
        box-shadow: var(--shadow);
      }

      .confirm-dialog::backdrop {
        background: rgb(3 7 18 / 0.78);
        backdrop-filter: blur(8px);
      }

      .dialog-content {
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3.25rem;
        height: 3.25rem;
        margin-block-end: 1rem;
        place-items: center;
        border: 1px solid rgb(244 63 94 / 0.34);
        border-radius: 1rem;
        background: rgb(244 63 94 / 0.13);
        color: var(--danger-strong);
        font-size: 1.65rem;
        font-weight: 900;
      }

      .dialog-copy {
        color: var(--muted);
      }

      .dialog-actions {
        display: flex;
        flex-direction: row-reverse;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin-block-start: 1.5rem;
      }

      .dialog-actions .button {
        flex: 1 1 10rem;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .preview-card,
        .confirm-dialog,
        .button,
        .dialog-icon,
        .preview-image {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const image = {
        title: "Midnight ridge",
        description: "A stylized landscape preview with deep blue mountains and a warm moon.",
        libraryName: "Travel edits"
      };

      function Button({ className = "", label, type = "button", dataAction }) {
        const actionAttribute = dataAction ? ` data-action="${dataAction}"` : "";
        return `<button type="${type}" class="button ${className}"${actionAttribute}>${label}</button>`;
      }

      function ImagePreview({ item }) {
        return `
          <main id="main-content" class="app-shell">
            <article class="preview-card" aria-labelledby="page-title">
              <figure class="image-frame">
                <div class="image-wrap">
                  <div class="preview-image" role="img" aria-label="${item.description}"></div>
                </div>
                <figcaption class="caption">
                  <div class="caption-text">
                    <p class="eyebrow">${item.libraryName}</p>
                    <h1 id="page-title">${item.title}</h1>
                    <p>${item.description}</p>
                  </div>
                  <div class="button-row">
                    ${Button({
                      className: "button-danger trigger",
                      label: "Delete image",
                      dataAction: "open-delete-dialog"
                    })}
                  </div>
                </figcaption>
              </figure>
            </article>
          </main>
        `;
      }

      function DeleteDialog({ item }) {
        return `
          <dialog class="confirm-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
            <div class="dialog-content">
              <div class="dialog-icon" aria-hidden="true">!</div>
              <div class="dialog-copy">
                <h2 id="dialog-title">Delete this image?</h2>
                <p id="dialog-description">
                  This will remove "${item.title}" from your ${item.libraryName} library. This action cannot be undone.
                </p>
              </div>
              <div class="dialog-actions">
                ${Button({
                  className: "button-danger",
                  label: "Delete image",
                  dataAction: "confirm-delete"
                })}
                ${Button({
                  className: "button-secondary",
                  label: "Cancel",
                  dataAction: "close-delete-dialog"
                })}
              </div>
            </div>
          </dialog>
        `;
      }

      function App() {
        return `${ImagePreview({ item: image })}${DeleteDialog({ item: image })}`;
      }

      const app = document.querySelector("#app");
      app.innerHTML = App();

      const dialog = document.querySelector(".confirm-dialog");
      const trigger = document.querySelector(".trigger");
      const cancelButton = dialog.querySelector('[data-action="close-delete-dialog"]');
      const confirmButton = dialog.querySelector('[data-action="confirm-delete"]');

      trigger.addEventListener("click", () => {
        dialog.showModal();
        cancelButton.focus();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close("cancel");
      });

      confirmButton.addEventListener("click", () => {
        dialog.close("delete");
      });

      dialog.addEventListener("click", (event) => {
        if (event.target === dialog) {
          dialog.close("cancel");
        }
      });
    </script>
  </body>
</html>
